#include <iostream>
#include <memory>
#include <utility>
int main() {
    int value=0, delta=0;
    std::cin >> value >> delta;
    auto source = std::make_unique<int>(value);
    const int* original = source.get();
    auto target = std::make_unique<int>(0);
    // TODO: trasferisci source in target, sostituendo la vecchia risorsa.
    target = std::move(source);
    bool empty_source = !source;
    bool same_resource = target.get() == original;
    // TODO: ricrea source con un nuovo intero value + delta.
    source = std::make_unique<int>(value + delta);
    std::cout << empty_source << ' ' << same_resource << ' '
              << *target << ' ' << *source << '\n';
}

